import { z } from "zod";
import { MAX_CLIENT_MESSAGE_ID, MAX_MESSAGE_BODY } from "./live-chat.constants.js";

const CONTROL_CHARS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

export const customerMessageSchema = z.object({
  body: z
    .string()
    .transform((value) => value.replace(/\r\n?/g, "\n").replace(CONTROL_CHARS, "").trim())
    .pipe(z.string().min(1, "Required").max(MAX_MESSAGE_BODY)),
  /** Generated by the browser per message and reused on retry. */
  clientId: z
    .string()
    .regex(/^[A-Za-z0-9_-]+$/, "Invalid client id")
    .min(8)
    .max(MAX_CLIENT_MESSAGE_ID)
    .nullish()
    .transform((value) => value ?? null),
});

export type CustomerMessageInput = z.infer<typeof customerMessageSchema>;

/** `POST /customer/session`. The desk conversation id from the handoff reply. */
export const customerSessionSchema = z.object({
  handoffId: z.string().trim().pipe(z.uuid()),
});

export type CustomerSessionInput = z.infer<typeof customerSessionSchema>;

export const typingSchema = z.object({ typing: z.boolean() });

/** A message id from `Last-Event-ID`, or null when absent or malformed. */
export function parseCursor(value: string | undefined): string | null {
  return value && /^\d{1,18}$/.test(value) ? value : null;
}
